# Optional preview (run from the repository root): Rscript code/16_preview_antibiotic_alignment.R COMPLETED_RUN_ID
suppressPackageStartupMessages({library(dplyr);library(tidyr);library(readr);library(lubridate);library(ggplot2)})
source("utils/clif_io.R");source("utils/preflight.R");source("utils/ase.R");source("utils/culture_timing_preview.R")
args<-commandArgs(trailingOnly=TRUE);if(length(args)!=1)stop("Supply a completed parent run ID")
parent<-args[[1]];manifest<-jsonlite::read_json(project_path("output","runs",parent,"provenance","run_manifest.json"))
stopifnot(identical(manifest$analysis_status,"completed"),identical(manifest$study_start_date,study_settings$study_start_date),identical(manifest$study_end_date,study_settings$study_end_date))
start<-safe_ts(study_settings$study_start_date);end<-safe_ts(study_settings$study_end_date)+days(1)
private<-project_path("data","intermediate","runs",parent,"antibiotic_alignment_preview");dir.create(private,recursive=TRUE,showWarnings=FALSE)
out<-project_path("output","review_figures",parent,"antibiotic_alignment");dir.create(out,recursive=TRUE,showWarnings=FALSE)
classification_file<-project_path("data","intermediate","runs",parent,"ase","ase_hospitalization_classification.csv")
episode_file<-project_path("data","intermediate","runs",parent,"ase","ase_blood_culture_criteria.csv")
classification<-read_clif_csv(classification_file,show_col_types=FALSE)
episodes<-read_clif_csv(episode_file,show_col_types=FALSE)
# Vasopressors must belong to a qualifying primary ASE episode, not simply occur at any time.
vaso<-episodes %>% filter(ase_without_lactate,!is.na(vasopressor_dttm)) %>% distinct(hospitalization_id) %>% mutate(qualifying_vasopressor=TRUE)
groups<-c("Suspected infection without ASE","ASE without vasopressor","ASE + vasopressor")
a<-classification %>% filter(ase_group!="No presumed infection") %>% left_join(vaso,by="hospitalization_id") %>% mutate(infection_group=case_when(ase_group=="Presumed infection without ASE"~groups[1],coalesce(qualifying_vasopressor,FALSE)~groups[3],TRUE~groups[2]))
h<-read_tbl("hospitalization") %>% mutate(across(c(admission_dttm,discharge_dttm),safe_ts)) %>% semi_join(classification,by="hospitalization_id")
stopifnot(!anyDuplicated(h$hospitalization_id),!anyDuplicated(a$hospitalization_id),all(classification$hospitalization_id %in% h$hospitalization_id))
stays<-merge_icu_stays(read_tbl("adt"),h)
# An explicit antibacterial allowlist avoids antifungals/antivirals and miscoded drugs in the source CMS group.
antibacterials<-c("amikacin","amoxicillin","amoxicillin_clavulanate","ampicillin","ampicillin_sulbactam","azithromycin","aztreonam","cefadroxil","cefazolin","cefdinir","cefepime","cefiderocol","cefixime","cefoxitin","cefpodoxime","ceftaroline","ceftazidime","ceftazidime_avibactam","ceftolozane_tazobactam","ceftriaxone","cephalexin","ciprofloxacin","clarithromycin","clindamycin","daptomycin","dicloxacillin","doxycycline","ertapenem","erythromycin","fidaxomicin","fosfomycin","gentamicin","imipenem","imipenem_relebactam","levofloxacin","linezolid","meropenem","metronidazole","minocycline","nitrofurantoin","oxacillin","penicillin","piperacillin_tazobactam","quinupristin_dalfopristin","rifampin","streptomycin","sulbactam_durlobactam","sulfadiazine","tedizolid","tetracycline","tigecycline","tobramycin","trimethoprim","trimethoprim_sulfamethoxazole","vancomycin")
con<-ase_connect(file.path(private,"duckdb_tmp"))
ase_register_sources(con,c(medication_admin_intermittent=find_table_path("medication_admin_intermittent")),h$hospitalization_id)
ase_standardize_sources(con,"medication_admin_intermittent")
quoted<-paste(DBI::dbQuoteString(con,antibacterials),collapse=",")
doses<-DBI::dbGetQuery(con,paste0("SELECT hospitalization_id,min(admin_dttm) first_antibiotic_dttm FROM src_medication_admin_intermittent WHERE med_category IN (",quoted,") AND mar_action_group='administered' AND med_dose>0 AND med_route_category IN ('iv','im','enteral','po','oral','intravenous','intramuscular') GROUP BY 1")) %>% mutate(first_antibiotic_dttm=safe_ts(first_antibiotic_dttm))
a<-a %>% left_join(doses,by="hospitalization_id") %>% inner_join(select(h,hospitalization_id,admission_dttm,discharge_dttm),by="hospitalization_id") %>% mutate(anchor_status=case_when(is.na(first_antibiotic_dttm)~"No recorded antibacterial dose",first_antibiotic_dttm<admission_dttm-days(2)|first_antibiotic_dttm>=discharge_dttm~"First dose outside hospitalization/ED window",first_antibiotic_dttm<start|first_antibiotic_dttm>=end~"First dose outside study",TRUE~"Included"))
qc<-count(a,infection_group,anchor_status,name="n_hospitalizations")
a<-filter(a,anchor_status=="Included")
# Preserve associated ED cultures up to two calendar days before admission, as in the ASE extraction.
# These plots use a fixed hospitalization denominator, not an invented pre-admission exposure interval.
intervals<-h %>% transmute(hospitalization_id,in_dttm=admission_dttm-days(2),out_dttm=discharge_dttm,location_category="icu")
full<-build_culture_data(h,intervals,read_timing_cultures(con,h$hospitalization_id),overrides=read_csv(project_path("config","specimen_category_overrides.csv"),show_col_types=FALSE))
DBI::dbDisconnect(con,shutdown=TRUE)
collections<-full$events %>% filter(collect_dttm>=start,collect_dttm<end)
# Blood bottles/orders at the same timestamp are collapsed, consistently with the earlier information plot.
blood<-collections %>% filter(fluid_category=="blood_buffy") %>% distinct(hospitalization_id,collect_dttm)
e<-bind_rows(blood %>% mutate(specimen="Blood"),collections %>% select(hospitalization_id,collect_dttm) %>% mutate(specimen="All specimens")) %>% inner_join(select(a,hospitalization_id,infection_group,first_antibiotic_dttm),by="hospitalization_id") %>% mutate(relative_hour=as.numeric(difftime(collect_dttm,first_antibiotic_dttm,units="hours"))) %>% filter(relative_hour>=-48,relative_hour<72) %>% mutate(bin_start_hour=floor(relative_hour))
n<-count(a,infection_group,name="n_hospitalizations")
counts<-count(e,infection_group,specimen,bin_start_hour,name="n_collections")
profile<-crossing(infection_group=groups,specimen=c("Blood","All specimens"),bin_start_hour=-48:71) %>% left_join(counts,by=c("infection_group","specimen","bin_start_hour")) %>% left_join(n,by="infection_group") %>% mutate(n_collections=coalesce(n_collections,0L),collections_per_100_hospitalizations=100*n_collections/n_hospitalizations,infection_group=factor(infection_group,levels=groups),specimen=factor(specimen,levels=c("Blood","All specimens")))
stopifnot(sum(profile$n_collections)==nrow(e),!anyDuplicated(a$hospitalization_id),all(e$bin_start_hour>=-48&e$bin_start_hour<72),sum(n$n_hospitalizations)==nrow(a))
# Hospitalization-level probability: all anchored hospitalizations, including those with no culture.
patient_counts<-e %>% group_by(hospitalization_id,specimen) %>% summarise(n_before=sum(relative_hour<0),n_tied=sum(relative_hour==0),n_after=sum(relative_hour>0),n_before_24h=sum(relative_hour>=-24&relative_hour<0),.groups="drop")
p<-crossing(select(a,hospitalization_id,infection_group,first_antibiotic_dttm,admission_dttm),specimen=c("Blood","All specimens")) %>% left_join(patient_counts,by=c("hospitalization_id","specimen")) %>% mutate(across(c(n_before,n_tied,n_after,n_before_24h),~coalesce(.x,0L)),observed_24h_before=first_antibiotic_dttm>=pmax(admission_dttm,start)+hours(24))
summary<-p %>% group_by(infection_group,specimen) %>% summarise(n_hospitalizations=n(),n_any_before=sum(n_before>0),percent_any_before=100*mean(n_before>0),percent_any_before_24h=100*mean(n_before_24h>0),n_any_tied=sum(n_tied>0),n_any_after=sum(n_after>0),n_no_culture_in_window=sum(n_before+n_tied+n_after==0),n_collections_before=sum(n_before),n_collections_tied=sum(n_tied),n_collections_after=sum(n_after),percent_collections_before=100*sum(n_before)/sum(n_before+n_tied+n_after),n_with_24h_hospital_observation=sum(observed_24h_before),percent_before_24h_with_full_observation=if(any(observed_24h_before))100*mean(n_before_24h[observed_24h_before]>0) else NA_real_,.groups="drop") %>% mutate(infection_group=factor(infection_group,levels=groups)) %>% arrange(specimen,infection_group)
colors<-setNames(c("#0072B2","#E69F00","#D55E00"),groups)
g<-ggplot(profile,aes(bin_start_hour,collections_per_100_hospitalizations,color=infection_group))+geom_step(linewidth=.8,direction="hv")+geom_vline(xintercept=0,linetype="dotted",linewidth=.7)+facet_wrap(~specimen,ncol=1,scales="free_y")+scale_color_manual(values=colors,name=NULL)+scale_x_continuous(breaks=seq(-48,72,12))+labs(title=paste(clif_site_name,"— Culture timing around first antibiotic administration"),x="Hours from first recorded antibacterial administration",y="Collections per 100 hospitalizations in each one-hour bin")+theme_bw(base_size=12)+theme(legend.position="bottom")
ggsave(file.path(out,paste0("culture_timing_first_antibiotic_",clif_site_name,".png")),g,width=13,height=8,dpi=200)
# Compare blood timing across antibiotic start locations without excluding between-stay anchors from the main graph.
ph<-anchor_antibiotic_phase(transmute(a,hospitalization_id,marker_time=first_antibiotic_dttm,marker_type="First antibacterial administration"),stays,start,end) %>% select(hospitalization_id,anchor_phase)
phases<-c("Before first ICU entry","First 24 ICU hours","After 24 ICU hours","Between/after ICU stays")
phase_n<-a %>% left_join(ph,by="hospitalization_id") %>% count(infection_group,anchor_phase,name="n_hospitalizations")
phase_counts<-e %>% filter(specimen=="Blood") %>% left_join(ph,by="hospitalization_id") %>% count(infection_group,anchor_phase,bin_start_hour,name="n_collections")
phase_profile<-crossing(infection_group=groups,anchor_phase=phases,bin_start_hour=-48:71) %>% left_join(phase_counts,by=c("infection_group","anchor_phase","bin_start_hour")) %>% left_join(phase_n,by=c("infection_group","anchor_phase")) %>% mutate(n_collections=coalesce(n_collections,0L),collections_per_100_hospitalizations=100*n_collections/n_hospitalizations,infection_group=factor(infection_group,levels=groups),anchor_phase=factor(anchor_phase,levels=phases))
stopifnot(sum(phase_profile$n_collections)==sum(e$specimen=="Blood"),sum(phase_n$n_hospitalizations)==nrow(a))
gp<-ggplot(phase_profile,aes(bin_start_hour,collections_per_100_hospitalizations,color=infection_group))+geom_step(linewidth=.7,direction="hv",na.rm=TRUE)+geom_vline(xintercept=0,linetype="dotted")+facet_wrap(~anchor_phase,ncol=2)+scale_color_manual(values=colors,name=NULL)+labs(title=paste(clif_site_name,"— Blood cultures by location of antibiotic start"),x="Hours from first recorded antibacterial administration",y="Blood collection timestamps per 100 hospitalizations per hour")+theme_bw(base_size=12)+theme(legend.position="bottom")
ggsave(file.path(out,paste0("blood_timing_first_antibiotic_by_icu_phase_",clif_site_name,".png")),gp,width=13,height=8,dpi=200)
write_csv(profile,file.path(out,"hourly_culture_timing.csv"));write_csv(summary,file.path(out,"before_antibiotic_summary.csv"));write_csv(qc,file.path(out,"anchor_qc.csv"));write_csv(phase_profile,file.path(out,"hourly_blood_timing_by_icu_phase.csv"));write_csv(phase_n,file.path(out,"anchor_phase_counts.csv"))
write_csv(a,file.path(private,"antibiotic_anchors.csv"));write_csv(p,file.path(private,"patient_timing.csv"))
jsonlite::write_json(list(parent_run=parent,script_md5=unname(tools::md5sum("code/16_preview_antibiotic_alignment.R")),helper_md5=unname(tools::md5sum("utils/culture_timing_preview.R")),classification_md5=unname(tools::md5sum(classification_file)),episodes_md5=unname(tools::md5sum(episode_file)),antibacterial_allowlist=antibacterials,routes=c("iv","im","enteral","po","oral","intravenous","intramuscular"),anchor="First actual administered positive-dose antibacterial timestamp for the hospitalization; not QAD midnight, not necessarily the start of the qualifying infection episode; prophylaxis and enteral antibiotics included",groups="Mutually exclusive retrospective hospitalization classifications; vasopressor must occur in a qualifying primary ASE episode; not a validated Sepsis-3 shock definition",collection_window_hours=c(-48,72),denominator="All included antibiotic-anchored hospitalizations in each group; fixed denominator includes uncultured people; rates are per hospitalization, not observed patient-hour exposure",culture_bounds="Hospital-associated cultures from admission minus 48 hours to discharge, clipped to study dates; pre-admission MAR may reflect ED treatment; missing outpatient/pre-transfer treatment is not captured",timing="Strict before (<0), exact ties (=0), strict after (>0); ties are not proof of pre-antibiotic collection; plotted zero-hour bin includes ties and later collections within one hour",selection_caution="Presumed infection and ASE require culture and antimicrobial criteria; group differences are partly selected by these definitions, not causal or prospective severity discrimination"),file.path(out,"provenance.json"),pretty=TRUE,auto_unbox=TRUE)
print(summary,width=Inf);print(qc);message("Preview saved: ",out)
